#!/usr/bin/env python3
"""Regenerate the K2-Horizon token-parity reference fixtures.

INDEPENDENT reference for the Rust engine's forward parity gate. Loads the
model through mlx-lm's official remote-code loader plus the model's own
`k2_horizon.py`, applies the model's chat template to the user prompt (this is
an instruct model — the raw prompt degenerates into repetition), then generates
N greedy (argmax) tokens. Prints, and writes next to this script:

  k2_horizon_prompt_ids.txt    the templated prompt token ids (the gate's input)
  k2_horizon_token_parity.txt  the greedy continuation the engine must reproduce

The engine is never in this loop, so the gate compares the engine against an
outside oracle, not against itself.

Usage (inside a uv reference env), passing the model directory explicitly:

    MODEL_DIR=/path/to/K2-Horizon-3.7B-4bit \
      uv run --python 3.12 --with mlx-lm --with transformers --with torch \
        python gen_reference_fixture.py

Keep N_TOKENS and USER_PROMPT in sync with the Rust test
`crates/serve/tests/forward_per_weight_quant.rs::k2_horizon_token_parity`.
"""
import os
import sys
from pathlib import Path

import mlx.core as mx
from mlx_lm.utils import load_model, load_tokenizer

USER_PROMPT = "What color is a ripe banana? Answer in one word."
N_TOKENS = 34

model_dir = os.environ.get("MODEL_DIR")
if not model_dir:
    sys.exit("set MODEL_DIR to the K2-Horizon-3.7B-4bit model directory")
model_dir = Path(model_dir).expanduser().resolve()

model, config = load_model(model_dir, trust_remote_code=True)
tokenizer = load_tokenizer(model_dir)

msgs = [{"role": "user", "content": USER_PROMPT}]
prompt_ids = list(tokenizer.apply_chat_template(msgs, add_generation_prompt=True))

generated = []
cur = list(prompt_ids)
for _ in range(N_TOKENS):
    logits = model(mx.array(cur)[None])  # [1, T, vocab]
    tok = int(mx.argmax(logits[:, -1, :], axis=-1).item())
    generated.append(tok)
    cur.append(tok)

here = Path(__file__).resolve().parent
(here / "k2_horizon_prompt_ids.txt").write_text(
    "# Templated prompt token ids for the K2-Horizon token-parity gate.\n"
    "# Regenerated by gen_reference_fixture.py; see that file for details.\n"
    + ",".join(map(str, prompt_ids)) + "\n"
)
(here / "k2_horizon_token_parity.txt").write_text(
    "# Reference greedy continuation for the K2-Horizon token-parity gate.\n"
    "# Regenerated by gen_reference_fixture.py; see that file for details.\n"
    + ",".join(map(str, generated)) + "\n"
)
print("templated_prompt_ids=" + ",".join(map(str, prompt_ids)))
print("generated=" + ",".join(map(str, generated)))
